import type {DiagramContent} from '../../../src/drawing/core/model'
/** Synthetic engineering reconstructions of the three supplied screenshots.
 * Only visible nodes/relations are retained; no inferred infrastructure links. */
const base=(id:string,title:string,kind:DiagramContent['kind']):DiagramContent=>({schemaVersion:1,id,title,kind,nodes:[],edges:[],lanes:[],phases:[],groups:[]})
export function layerHeaders(){const c=base('quality-layer-headers','双卡计算与内存缓存','architecture');c.groups=[{id:'access',label:'接入与调度'},{id:'inference',label:'推理与缓存'},{id:'resources',label:'计算与存储'}];c.nodes=[{id:'gateway',kind:'module',label:'网关与任务队列',groupId:'access',items:['按并发预算准入','超长请求单独限流']},{id:'model',kind:'module',label:'模型推理服务',groupId:'inference',items:['单副本双卡并行','热缓存留在计算设备']},{id:'cache',kind:'module',label:'内存缓存',groupId:'inference',items:['缓存复用','按容量淘汰']},{id:'compute',kind:'module',label:'双卡计算资源',groupId:'resources',items:['同机卡间通信','按需启用']},{id:'storage',kind:'module',label:'持久化存储',groupId:'resources',items:['模型与数据','任务运行记录']}];c.edges=[{id:'admit',source:'gateway',target:'model',label:'准入请求'},{id:'write',source:'model',target:'cache',label:'缓存写入'},{id:'hit',source:'cache',target:'model',label:'命中加载',kind:'feedback'}];return c}
export function componentCollaboration(){const c=base('quality-component-collaboration','统一网关与计算服务协作','dataflow');c.groups=[{id:'access',label:'应用接入'},{id:'providers',label:'计算服务'},{id:'output',label:'业务输出'}];c.nodes=[{id:'gateway',kind:'module',groupId:'access',label:'统一应用网关',description:'按授权、模型版本和任务类别分流；按并发预算排队。'},{id:'dual',kind:'module',groupId:'providers',label:'双卡计算端点',description:'处理需要指定量化模型的超长请求。'},{id:'api',kind:'module',groupId:'providers',label:'授权模型服务',description:'处理经授权的通用请求。'},{id:'single',kind:'module',groupId:'providers',label:'单卡计算端点',description:'处理定制与常规请求。'},{id:'result',kind:'module',groupId:'output',label:'业务结果',description:'汇聚各端点的模型输出。'}];c.edges=[{id:'long',source:'gateway',target:'dual',label:'指定模型请求'},{id:'api-route',source:'gateway',target:'api',label:'授权请求'},{id:'custom',source:'gateway',target:'single',label:'定制与常规请求'},{id:'dual-out',source:'dual',target:'result',label:'模型输出'},{id:'api-out',source:'api',target:'result',label:'模型输出'},{id:'single-out',source:'single',target:'result',label:'模型输出'}];c.groups=[];c.nodes=c.nodes.map(({groupId,...node})=>({...node,kind:'card' as const}));return c}
export function wideMindmap(){const c=base('quality-compact-mindmap','三类计算部署路径','mindmap');c.nodes=[{id:'root',kind:'topic',label:'模型部署'},{id:'cloud',kind:'topic',label:'云计算自部署',parentId:'root'},{id:'local',kind:'topic',label:'内部计算采购',parentId:'root'},{id:'hybrid',kind:'topic',label:'模型服务与云计算',parentId:'root'}];for(const [parent,labels]of [['cloud',['同机双卡','单副本并行','按需调度']],['local',['双卡服务器','整机采购预算','运行资源预算']],['hybrid',['单卡与授权服务','弹性运行预算','按权限和任务分流']]] as const)labels.forEach((label,i)=>c.nodes.push({id:parent+'-'+i,kind:'topic',label,parentId:parent}));return c}
export function compactFlow(){const c=base('quality-compact-flow','按授权分配模型请求','flowchart');c.nodes=[{id:'start',kind:'start',label:'接收模型请求'},{id:'auth',kind:'decision',label:'具备服务授权？',description:'保留授权详情供业务属性面板读取，参数不撑大流程节点。'},{id:'accept',kind:'task',label:'提交授权服务',description:'按已授权模型版本调用服务并记录追踪标识。'},{id:'reject',kind:'task',label:'提示申请授权',description:'授权不足时提示申请，不代替业务判断出口。'},{id:'end',kind:'end',label:'返回处理结果'}];c.edges=[{id:'start-auth',source:'start',target:'auth'},{id:'yes',source:'auth',target:'accept',label:'是'},{id:'no',source:'auth',target:'reject',label:'否'},{id:'done',source:'accept',target:'end'},{id:'not-authorized',source:'reject',target:'end'}];return c}
